'use strict';
// MS13c scratch (from MS10b's long-chain-scan.js): the long-chain corpus of core/tests/suites/tech-chain.test.js
// (LONG_CHAIN_PUZZLES: real minimal classic9 puzzles dug by SG.testkit.dig from the seeded stream 161, fork
// 'minimal.<i>'), regenerated by index under the GROUPED ladder of MS13c. A puzzle qualifies when the stuck position
// after every technique below forcingChainLong with C = 6 (the registered grouped forcingChain included) has a shortest
// proof of 7 or 8 links in the complete grouped graph (the grouped seam with the registered limits, no fallback, no
// cap), so that the registered forcingChainLong fires on it. Prints the puzzle lines of the qualifying indices.
// Usage (from generator/): node tests/artifacts/difficulty-v3/MS13c/long-chain-scan.js <from> <count>
const SG = require('./load.js');
const H = SG.techHelper;
const m9 = H.model('classic9');
const CS = SG.chainSearch;
const from = Number(process.argv[2] || 0);
const count = Number(process.argv[3] || 100);
const below = SG.techniques.list().filter((t) => t.variantScope === null &&
  SG.techniques.get('forcingChainLong').order > t.order).map((t) => t.id);
const rng = SG.testkit.rng.create(161);
const t0 = Date.now();
let qualifying = 0;
let solved = 0;
let capped = 0;
for (let i = from; i < from + count; i++) {
  const r = rng.fork('minimal.' + i);
  const solution = SG.testkit.randomSolution(m9, r.fork('grid'));
  const dug = SG.testkit.dig(m9, solution, r.fork('dig'), { symmetry: 'none', minClues: 0 });
  const puzzle = H.puzzleString(m9, dug.givens);
  const before = CS.SHORT_MAX;
  CS.SHORT_MAX = 6;
  let state;
  try { state = H.stateAfter(m9, puzzle, below); } finally { CS.SHORT_MAX = before; }
  if (state.unsolvedCount === 0) { solved++; continue; }
  const records = [];
  const ctx = SG.techniques.createContext(m9, { onPatternWork: (rec) => records.push(rec) });
  const seam = CS.groupedForcing(m9, state, ctx, { id: 'x', minLength: 1, maxLength: 12 });
  if (records[0].grouped.stop !== null) { capped++; continue; }
  if (seam === null) continue;
  const len = seam.i18nArgs.length;
  if (len !== 7 && len !== 8) continue;
  qualifying++;
  console.log("'" + puzzle + "', // #" + i + ': ' + len + ' links' + (seam.i18nArgs.proofVersion === 2 ? ' (groups)' : ''));
}
console.error('scanned ' + count + ' from ' + from + ', qualifying ' + qualifying + ', solved by the grouped ladder ' +
  solved + ', capped ' + capped + ', ' + ((Date.now() - t0) / 1000).toFixed(1) + ' s');
